# ───────────── av05: 10 Prompt Mistakes That Break AI Agents ─────────────
def MIS(n, name, symptom, why, bad, good, fix_say, extra=None):
    out = [CH(n, "Mistake %d: %s" % (n, name), "Mistake नंबर %d: %s।" % (n, name), [name.split()[0]], name.split()[0]),
           b("card", dict(icon="x", title="Symptom", rows=[["क्या दिखता है", symptom]]), "Symptom: " + symptom + "।", "Symptom"),
           b("card", dict(icon="cpu", title="क्यों होता है", rows=[["Reason", why]]), "ऐसा क्यों होता है? " + why + "।", "क्यों"),
           b("versus", dict(bad=bad, good=good), fix_say, "fix")]
    if extra:
        out += extra if isinstance(extra, list) else [extra]
    return out


